// React 19: a form action with useActionState
async function createProduct(prev: FormState, formData: FormData): Promise<FormState> {
  const res = await fetch("/api/products", { method: "POST", body: formData });
  if (res.status === 422) return { fieldErrors: (await res.json()).errors, formError: null };
  if (!res.ok) return { fieldErrors: {}, formError: "Something went wrong. Try again." };
  return { fieldErrors: {}, formError: null, savedId: (await res.json()).id };
}

function NewProductForm() {
  const [state, formAction, isPending] = useActionState(createProduct, { fieldErrors: {}, formError: null });
  return (
    <form action={formAction}>
      <input name="sku" aria-invalid={state.fieldErrors.sku ? true : undefined} />
      {state.fieldErrors.sku && <p>{state.fieldErrors.sku}</p>}
      {state.formError && <p role="alert">{state.formError}</p>}
      <button type="submit" disabled={isPending}>{isPending ? "Saving..." : "Save"}</button>
    </form>
  );
}
